-- rowstile 0.1.0-dev: scim_groups. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', 'edd1d0df29e5d43d', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'edd1d0df29e5d43d' THEN
    PERFORM pg_catalog.set_config('authz_migration.read_only', pg_catalog.current_setting('default_transaction_read_only'), false);
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'edd1d0df29e5d43d' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only until the migration''s last statement; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = 'edd1d0df29e5d43d' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM 'fa3080e8fb2c50cf' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      'fa3080e8fb2c50cf', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'conf_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- Inheritance tables kept whose tables have other tables under them since they were computed (a partition
-- attached or detached: no trigger saw those rows) are computed again
DO $stale$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;
  FOR r IN SELECT n.name, n.oids, n.fn FROM (VALUES ('folder__parent__tree', ARRAY[to_regclass('"app"."folders"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"app"."folders"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."folder__parent__tree_rebuild"()')) n(name, oids, fn)
           JOIN authz_int.trees t ON t.name = n.name
           WHERE t.oids IS DISTINCT FROM n.oids AND to_regprocedure(n.fn) IS NOT NULL LOOP
    EXECUTE format('SELECT %s', r.fn);
    UPDATE authz_int.trees SET oids = r.oids WHERE name = r.name;
  END LOOP;
END $stale$;

-- What the app role evaluates itself (its rules, the views they read, the rules' own functions, the masked views)
-- calls nothing of the app's that may read data: a call the condition's text doesn't show isn't run as the owner
DO $ac$
DECLARE r record;
BEGIN
  FOR r IN
    WITH RECURSIVE read(classid, objid, what) AS (
      SELECT x.classid, x.objid, x.what FROM (
        SELECT 'pg_policy'::regclass::oid AS classid, p.oid AS objid,
               format('the %s rule of %s', substr(p.polname::text, 7), p.polrelid::regclass) AS what
        FROM pg_policy p JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
         AND d.description IN ('rowstile')
        UNION ALL
        SELECT 'pg_proc'::regclass::oid, f.oid, 'the rules of ' || split_part(f.proname::text, ':', 1)
        FROM pg_proc f WHERE f.pronamespace = 'authz_gen'::regnamespace
        UNION ALL
        SELECT 'pg_rewrite'::regclass::oid, w.oid, 'the masked view ' || c.oid::regclass
        FROM pg_class c JOIN pg_description d ON d.objoid = c.oid AND d.classoid = 'pg_class'::regclass
         AND d.description IN ('rowstile masked view')
        JOIN pg_rewrite w ON w.ev_class = c.oid) x
      UNION
      -- (the views they read, and those these read: a view runs what it calls as whoever reads it)
      SELECT 'pg_rewrite'::regclass::oid, w.oid, rd.what
      FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
       AND dep.refclassid = 'pg_class'::regclass
      JOIN pg_class v ON v.oid = dep.refobjid AND v.relkind = 'v' AND v.relnamespace = 'authz_int'::regnamespace
      JOIN pg_rewrite w ON w.ev_class = v.oid)
    SELECT rd.what, fn.oid::regprocedure::text AS fn
    FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
    JOIN pg_proc fn ON fn.oid = CASE dep.refclassid
        WHEN 'pg_proc'::regclass THEN dep.refobjid
        WHEN 'pg_operator'::regclass THEN (SELECT o.oprcode FROM pg_operator o WHERE o.oid = dep.refobjid) END
    WHERE fn.pronamespace NOT IN (SELECT n.oid FROM pg_namespace n
                                  WHERE n.nspname IN ('pg_catalog', 'authz', 'authz_gen', 'authz_int'))
      AND fn.provolatile <> 'i'
      AND fn.prolang NOT IN (SELECT l.oid FROM pg_language l WHERE l.lanname IN ('internal', 'c'))
    ORDER BY 1, 2 LIMIT 1
  LOOP
    RAISE EXCEPTION '%: a condition calls %, and nothing in its text shows the call (a function of the row read as a column, a cast, an operator written OPERATOR(...)), so the app role would run it with its own rights, not the policy''s [AZ628]', r.what, r.fn
      USING HINT = 'call it by its name, with parentheses, on the row''s columns, as {app.blocked_doc(this.id)}: rowstile then runs it with the policy''s rights. A function that reads nothing may be marked IMMUTABLE instead';
  END LOOP;
END $ac$;

-- the relations authz.sync_members takes: read from one table of members (group -> user), without where
CREATE FUNCTION authz_int.takes_members(p_relation text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce(p_relation = ANY (ARRAY['project.member']::text[]), false) $f$;

-- a group's members in that table, as ids, in the order of the users' keys (p_relation: type.relation)
CREATE FUNCTION authz_int.members_of(p_relation text, p_id text) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
BEGIN
  CASE $1
    WHEN 'project.member' THEN
      RETURN ARRAY(SELECT s."user_id"::text FROM "app"."members" s WHERE s."project_id" = $2::bigint ORDER BY s."user_id");
  END CASE;
END $f$;

-- SCIM (RFC 7644) answered in SQL: an identity provider's requests, as a route hands them on (authz.scim)
-- what a request is answered: a status, a body (none for 204) and, for what was made, where it is below the route
CREATE TYPE authz_int.scim_answer AS (status int, body jsonb, location text);

-- an error's body as SCIM writes it (RFC 7644, 3.12): the status as a text, the scimType where the RFC names one
CREATE FUNCTION authz_int.scim_error(p_status int, p_type text, p_detail text) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $f$
  SELECT jsonb_strip_nulls(jsonb_build_object('schemas', jsonb_build_array('urn:ietf:params:scim:api:messages:2.0:Error'),
                                              'status', p_status::text, 'scimType', p_type, 'detail', p_detail)) $f$;

-- a refusal of rowstile's own, its words ending with their code
CREATE FUNCTION authz_int.scim_no(p_status int, p_type text, p_detail text) RETURNS authz_int.scim_answer
LANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT ROW(p_status, authz_int.scim_error(p_status, p_type, p_detail || ' (rowstile help AZ721)'), NULL)::authz_int.scim_answer $f$;

-- ids as a list of members
CREATE FUNCTION authz_int.scim_values(p_ids text[]) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce(jsonb_agg(jsonb_build_object('value', x.id) ORDER BY x.i), '[]'::jsonb)
  FROM unnest(p_ids) WITH ORDINALITY x(id, i) $f$;

-- A part of a URL read: + is a space, %41 the byte 41 (the bytes then read as UTF-8); a % that starts no escape
-- is a %
CREATE FUNCTION authz_int.url_decode(p_text text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SET search_path = pg_catalog, pg_temp AS $f$
  SELECT convert_from(decode(coalesce(string_agg(CASE WHEN x.part[1] ~ '^%..$' THEN substr(x.part[1], 2)
                                                      ELSE encode(convert_to(x.part[1], 'UTF8'), 'hex') END, '' ORDER BY x.i), ''),
                             'hex'), 'UTF8')
  FROM regexp_matches(replace(p_text, '+', ' '), '%[0-9A-Fa-f]{2}|[^%]+|%', 'g') WITH ORDINALITY x(part, i) $f$;

-- A query string's parameters, by their names in lower case (a name given twice keeps its last value). NULL for
-- one whose escapes are no text (bytes that are no UTF-8, or that this database's encoding has no character for)
CREATE FUNCTION authz_int.scim_query(p_query text) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  RETURN (SELECT coalesce(jsonb_object_agg(lower(authz_int.url_decode(split_part(x.pair, '=', 1))),
                                           authz_int.url_decode(substr(x.pair, length(split_part(x.pair, '=', 1)) + 2)) ORDER BY x.i),
                          '{}'::jsonb)
          FROM unnest(string_to_array(coalesce(p_query, ''), '&')) WITH ORDINALITY x(pair, i) WHERE x.pair <> '');
EXCEPTION WHEN character_not_in_repertoire OR untranslatable_character THEN
  RETURN NULL;
END $f$;

-- A filter read: `attribute eq "value"`, joined by `and`, the attributes and the operators in any case (what
-- Microsoft Entra ID and Okta send), as a list of [attribute in lower case, value]. NULL for anything else
CREATE FUNCTION authz_int.scim_filter(p_filter text) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_rest text := p_filter; v_terms jsonb := '[]'; v_term text[];
BEGIN
  LOOP
    v_term := regexp_match(v_rest, E'^[[:space:]]*([A-Za-z][A-Za-z0-9_.:$-]*)[[:space:]]+[eE][qQ][[:space:]]+("(?:[^"\\\\]|\\\\.)*")[[:space:]]*(?:[aA][nN][dD][[:space:]]+(.*))?$');
    IF v_term IS NULL THEN
      RETURN NULL;
    END IF;
    v_terms := v_terms || jsonb_build_array(jsonb_build_array(lower(v_term[1]), v_term[2]::jsonb));
    IF v_term[3] IS NULL THEN
      RETURN v_terms;
    END IF;
    v_rest := v_term[3];
  END LOOP;
EXCEPTION WHEN invalid_text_representation THEN   -- a value with an escape JSON doesn't have
  RETURN NULL;
END $f$;

-- A column the settings name, of a table of the app's: its type. A column that is gone since they were set is an
-- error, saying so
CREATE FUNCTION authz_int.scim_column(p_table text, p_column text) RETURNS text
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_type text;
BEGIN
  SELECT format_type(a.atttypid, a.atttypmod) INTO v_type FROM pg_attribute a
  WHERE a.attrelid = to_regclass(p_table) AND a.attname = p_column AND a.attnum > 0 AND NOT a.attisdropped;
  IF v_type IS NULL THEN
    RAISE EXCEPTION 'the SCIM settings name the column % of %, which has none of that name now: set them again (authz.set_scim)',
      p_column, to_regclass(p_table) USING ERRCODE = 'object_not_in_prerequisite_state', HINT = 'rowstile help AZ722';
  END IF;
  RETURN v_type;
END $f$;

-- The members a request names (a list of {"value": a user's id}, or one of them), as ids the database writes.
-- p_there: each is a user's row, held until the transaction ends (a member added; one removed needs no row). why:
-- what is wrong with the first that isn't one
CREATE FUNCTION authz_int.scim_members(p_value jsonb, p_there boolean, OUT ids text[], OUT why text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_member jsonb; v_id text;
BEGIN
  ids := '{}';
  FOR v_member IN SELECT x.member FROM jsonb_array_elements(CASE jsonb_typeof(p_value) WHEN 'array' THEN p_value
                                                               WHEN 'object' THEN jsonb_build_array(p_value)
                                                               ELSE '[null]' END) WITH ORDINALITY x(member, i) ORDER BY x.i LOOP
    v_id := CASE WHEN jsonb_typeof(v_member->'value') IN ('string', 'number') THEN v_member->>'value' END;
    IF v_id IS NULL THEN
      why := 'a member is {"value": a user''s id}';
    ELSIF lower(coalesce(v_member->>'type', 'user')) <> 'user' THEN
      why := format('member %s is a %s: a group''s members are users here', v_id, v_member->>'type');
    ELSIF p_there AND NOT authz_int.hold('user', authz_int.canon('user', v_id)) THEN
      why := format('there is no user %s', v_id);
    END IF;
    EXIT WHEN why IS NOT NULL;
    v_id := authz_int.canon('user', v_id);
    IF v_id <> ALL (ids) THEN
      ids := ids || v_id;
    END IF;
  END LOOP;
END $f$;

-- A PATCH's operations applied to a group as it is (RFC 7644, 3.5.2): its members, its name, its externalId as
-- they are then; touched: an operation named the members. An operation without a path carries attributes in its
-- value, each read as an operation on it. scim_type and why: the first operation that can't be applied, and nothing
-- of the PATCH is
CREATE FUNCTION authz_int.scim_group_patch(p_operations jsonb, p_members text[], p_name text, p_external_id text,
  OUT members text[], OUT name text, OUT external_id text, OUT touched boolean, OUT scim_type text, OUT why text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE o record; m record; v_text boolean;
BEGIN
  members := p_members; name := p_name; external_id := p_external_id; touched := false;
  IF jsonb_typeof(p_operations) IS DISTINCT FROM 'array' OR jsonb_array_length(p_operations) = 0 THEN
    scim_type := 'invalidSyntax'; why := 'a PATCH carries Operations: a list of op, path and value';
    RETURN;
  END IF;
  FOR o IN
    SELECT lower(x.operation->>'op') AS op, coalesce(x.operation->>'path', a.key) AS path, x.operation->>'path' IS NOT NULL AS said,
           CASE WHEN x.operation->>'path' IS NULL THEN a.value ELSE x.operation->'value' END AS value
    FROM jsonb_array_elements(p_operations) WITH ORDINALITY x(operation, i)
    LEFT JOIN LATERAL jsonb_each(CASE WHEN x.operation->>'path' IS NULL AND jsonb_typeof(x.operation->'value') = 'object'
                                           AND lower(x.operation->>'op') IS DISTINCT FROM 'remove'
                                      THEN x.operation->'value' END) a ON true
    ORDER BY x.i, a.key
  LOOP
    v_text := jsonb_typeof(o.value) IS NOT DISTINCT FROM 'string';
    IF o.op IS NULL OR o.op NOT IN ('add', 'remove', 'replace') THEN
      scim_type := 'invalidSyntax'; why := format('op is add, remove or replace, not %s', coalesce(o.op, 'nothing'));
    ELSIF o.path IS NULL AND o.op = 'remove' THEN
      scim_type := 'noTarget'; why := 'a remove names what it removes: a path';
    ELSIF o.path IS NULL THEN
      scim_type := 'invalidValue'; why := 'an operation with no path carries its attributes in value';
    ELSIF lower(o.path) = 'members' AND o.op = 'remove' AND coalesce(jsonb_typeof(o.value), 'null') = 'null' THEN
      members := '{}'; touched := true;
    ELSIF lower(o.path) = 'members' THEN
      SELECT * INTO m FROM authz_int.scim_members(o.value, o.op <> 'remove');
      scim_type := CASE WHEN m.why IS NOT NULL THEN 'invalidValue' END; why := m.why;
      members := CASE o.op WHEN 'replace' THEN m.ids
                           WHEN 'add' THEN members || ARRAY(SELECT x.id FROM unnest(m.ids) WITH ORDINALITY x(id, i)
                                                            WHERE x.id <> ALL (members) ORDER BY x.i)
                           ELSE ARRAY(SELECT x.id FROM unnest(members) WITH ORDINALITY x(id, i)
                                      WHERE x.id <> ALL (m.ids) ORDER BY x.i) END;
      touched := true;
    ELSIF o.path ~* '^members[[][[:space:]]*value[[:space:]]+eq[[:space:]]+"[^"]*"[[:space:]]*[]]$' AND o.op = 'remove' THEN
      members := array_remove(members, authz_int.canon('user', split_part(o.path, '"', 2))); touched := true;
    ELSIF o.path ~* '^members[[]' THEN
      scim_type := 'invalidPath'; why := 'a path names one member for a remove alone, as members[value eq "id"]';
    ELSIF lower(o.path) = 'displayname' AND o.op <> 'remove' AND v_text AND o.value #>> '{}' <> '' THEN
      name := o.value #>> '{}';
    ELSIF lower(o.path) = 'displayname' THEN
      scim_type := 'invalidValue'; why := 'displayName: a group has a name, a text that isn''t empty';
    ELSIF lower(o.path) = 'externalid' AND (o.op = 'remove' OR v_text) THEN
      external_id := CASE WHEN o.op <> 'remove' THEN o.value #>> '{}' END;
    ELSIF lower(o.path) = 'externalid' THEN
      scim_type := 'invalidValue'; why := 'externalId: a text';
    ELSIF o.said OR lower(o.path) NOT IN ('id', 'schemas', 'meta') THEN   -- (what a value with no path says of those is no change)
      scim_type := 'invalidPath';
      why := format('%s is nothing of a group a PATCH changes here (displayName, externalId, members)', o.path);
    END IF;
    EXIT WHEN why IS NOT NULL;
  END LOOP;
END $f$;

-- The groups the settings open, as SCIM writes them, in the order of their keys, a page of them at most: those a
-- filter's terms name ([[attribute, value], ...]; none: all), with how many there are in all. A value is compared as
-- the column's type compares, so an index on the column finds it; one that is no value of that type finds nothing
CREATE FUNCTION authz_int.scim_groups(p_settings jsonb, p_terms jsonb, p_members boolean, OUT total bigint, OUT resources jsonb)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_type text := split_part(p_settings->>'group', '.', 1); t authz_int.types; v_term jsonb; v_id text; v_values text[] := '{}';
        v_where text := ''; v_order text; v_name text := p_settings->>'group_name'; v_external text := p_settings->>'group_external_id';
        v_column text; v_column_type text;
BEGIN
  SELECT * INTO t FROM authz_int.types x WHERE x.name = v_type;
  PERFORM authz_int.scim_column(t.tbl, v_name);
  IF v_external IS NOT NULL THEN
    PERFORM authz_int.scim_column(t.tbl, v_external);
  END IF;
  FOR v_term IN SELECT x.term FROM jsonb_array_elements(p_terms) WITH ORDINALITY x(term, i) ORDER BY x.i LOOP
    IF v_term->>0 = 'id' THEN
      -- (the key's type by a subquery, as authz_int.hold asks it)
      IF pg_input_is_valid(v_term->>1, (SELECT x.keytype FROM authz_int.types x WHERE x.name = v_type))
         AND authz_int.canon(v_type, v_term->>1) IS NOT DISTINCT FROM coalesce(v_id, authz_int.canon(v_type, v_term->>1)) THEN
        v_id := authz_int.canon(v_type, v_term->>1);
        v_where := v_where || ' AND ' || t.find;
      ELSE
        v_where := v_where || ' AND false';
      END IF;
    ELSE
      v_column := CASE v_term->>0 WHEN 'displayname' THEN v_name ELSE v_external END;
      IF v_column IS NULL THEN   -- (an externalId, and the settings name no column for it: no group has one)
        v_where := v_where || ' AND false';
      ELSE
        v_column_type := authz_int.scim_column(t.tbl, v_column);
        v_values := v_values || (v_term->>1);
        v_where := v_where || format(' AND x.%I = (CASE WHEN pg_input_is_valid($2[%s], (SELECT %L)) THEN $2[%s] END)::%s',
                                     v_column, cardinality(v_values), v_column_type, cardinality(v_values), v_column_type);
      END IF;
    END IF;
  END LOOP;
  v_order := (SELECT string_agg(format('x.%I', c.name), ', ' ORDER BY c.i) FROM unnest(string_to_array(t.pk, ', ')) WITH ORDINALITY c(name, i));
  -- (the row's own columns are named in the innermost query alone, where nothing else has a name)
  EXECUTE format(
    'SELECT coalesce(max(g.n), 0), coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('
    || '''schemas'', jsonb_build_array(''urn:ietf:params:scim:schemas:core:2.0:Group''), ''id'', g.id, ''externalId'', g.external_id, '
    || '''displayName'', g.name, ''meta'', jsonb_build_object(''resourceType'', ''Group''))) '
    || '|| CASE WHEN $4 THEN jsonb_build_object(''members'', authz_int.scim_values(authz_int.members_of($3, g.id))) ELSE ''{}''::jsonb END '
    || 'ORDER BY g.i), ''[]''::jsonb) '
    || 'FROM (SELECT %s AS id, x.%I::text AS name, %s AS external_id, count(*) OVER () AS n, row_number() OVER (ORDER BY %s) AS i '
    || 'FROM %s x WHERE true%s ORDER BY %s LIMIT %s) g',
    t.id_of, v_name, CASE WHEN v_external IS NULL THEN 'NULL::text' ELSE format('x.%I::text', v_external) END, v_order, t.tbl, v_where,
    v_order, coalesce((p_settings->>'page')::int, 100))
  INTO total, resources USING v_id, v_values, p_settings->>'group', p_members;
END $f$;

-- A group's row held until the transaction ends: two requests that change one group's members go one after the
-- other, the second from the members the first left (a lock that lets rows that name the group be written)
CREATE FUNCTION authz_int.scim_hold(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE t authz_int.types;
BEGIN
  SELECT * INTO t FROM authz_int.types x WHERE x.name = p_type;
  IF pg_input_is_valid(p_id, (SELECT x.keytype FROM authz_int.types x WHERE x.name = p_type)) THEN
    EXECUTE format('SELECT 1 FROM %s x WHERE %s FOR NO KEY UPDATE', t.tbl, t.find) USING p_id;
  END IF;
END $f$;

-- The app's function for a group or a user (the settings name it) called: p_id NULL makes the row, p_resource
-- NULL deletes it. Its answer, the row's key, or the refusal a route answers: 409 where a key or a name is another
-- row's, 400 with the function's own words for what it raised and for what a constraint refused. Anything else it
-- fails with is an error. It runs as the policy's owner, so it must be the owner's still: a role that may write its
-- body would otherwise run its own code with the owner's rights
CREATE FUNCTION authz_int.scim_call(p_function text, p_type text, p_id text, p_resource jsonb,
  OUT key text, OUT refusal authz_int.scim_answer)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT coalesce((SELECT r.rolsuper OR pg_has_role(p.proowner, n.nspowner, 'MEMBER')
                   FROM pg_proc p JOIN pg_roles r ON r.oid = p.proowner, pg_namespace n
                   WHERE p.oid = to_regprocedure(p_function || '(text, jsonb)') AND n.nspname = 'authz_int'), false) THEN
    RAISE EXCEPTION 'the function % the SCIM settings name is gone, or is no longer the policy''s owner''s: set them again (authz.set_scim)',
      p_function USING ERRCODE = 'object_not_in_prerequisite_state', HINT = 'rowstile help AZ722';
  END IF;
  BEGIN
    EXECUTE 'SELECT ' || p_function || '($1, $2)' INTO key USING p_id, p_resource;
  EXCEPTION
    WHEN unique_violation THEN
      refusal := ROW(409, authz_int.scim_error(409, 'uniqueness', SQLERRM), NULL)::authz_int.scim_answer;
      RETURN;
    WHEN raise_exception OR data_exception OR integrity_constraint_violation THEN
      refusal := ROW(400, authz_int.scim_error(400, 'invalidValue', SQLERRM), NULL)::authz_int.scim_answer;
      RETURN;
  END;
  IF p_resource IS NOT NULL AND NOT coalesce(authz_int.hold(p_type, authz_int.canon(p_type, key)), false) THEN
    RAISE EXCEPTION '% answered %, which is no %''s key: the function the SCIM settings name answers the key of the row it made or changed',
      p_function, coalesce(key, 'nothing'), p_type USING ERRCODE = 'object_not_in_prerequisite_state', HINT = 'rowstile help AZ722';
  END IF;
  key := authz_int.canon(p_type, key);
END $f$;

-- A request for the groups (p_id NULL) or for one: read, listed, made, replaced, patched, deleted. Everything a
-- request says is read before anything is written, the app's function is called before the members are, and what
-- fails after that is an error: so a request is done whole or not at all
CREATE FUNCTION authz_int.scim_group(p_settings jsonb, p_method text, p_id text, p_query jsonb, p_body jsonb)
RETURNS authz_int.scim_answer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_type text := split_part(p_settings->>'group', '.', 1); v_relation text := split_part(p_settings->>'group', '.', 2);
        v_function text := p_settings->>'group_function';
        v_members_too boolean := lower(coalesce(p_query->>'excludedattributes', '')) !~ '(^|,)[[:space:]]*members[[:space:]]*(,|$)';
        v_terms jsonb := '[]'; v_id text; v_now jsonb; v_name text; v_external text; v_members text[]; v_resource jsonb;
        g record; p record; m record; c record;
BEGIN
  IF NOT authz_int.takes_members(p_settings->>'group') THEN   -- (none named, or one the policy no longer has)
    RETURN authz_int.scim_no(501, NULL, 'the SCIM settings name no group to serve (authz.set_scim: group, a relation authz.sync_members takes)');
  ELSIF p_method = 'GET' AND p_id IS NULL THEN
    IF p_query ? 'filter' THEN
      v_terms := authz_int.scim_filter(p_query->>'filter');
    END IF;
    IF v_terms IS NULL OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_terms) x(term)
                                  WHERE x.term->>0 NOT IN ('displayname', 'externalid', 'id')) THEN
      RETURN authz_int.scim_no(400, 'invalidFilter',
                               'a filter here is attribute eq "value", joined by and, on displayName, externalId and id');
    END IF;
    SELECT * INTO g FROM authz_int.scim_groups(p_settings, v_terms, v_members_too);
    RETURN ROW(200, jsonb_build_object('schemas', jsonb_build_array('urn:ietf:params:scim:api:messages:2.0:ListResponse'),
                                       'totalResults', g.total, 'itemsPerPage', jsonb_array_length(g.resources),
                                       'startIndex', 1, 'Resources', g.resources), NULL)::authz_int.scim_answer;
  ELSIF (p_id IS NULL) <> (p_method = 'POST') OR p_method NOT IN ('GET', 'POST', 'PUT', 'PATCH', 'DELETE') THEN
    RETURN authz_int.scim_no(405, NULL, format('%s is no request Groups%s takes', p_method, coalesce('/' || p_id, '')));
  END IF;
  IF p_id IS NOT NULL THEN
    v_id := authz_int.canon(v_type, p_id);
    IF p_method <> 'GET' THEN
      PERFORM authz_int.scim_hold(v_type, v_id);
    END IF;
    SELECT x.resources->0 INTO v_now FROM authz_int.scim_groups(p_settings, jsonb_build_array(jsonb_build_array('id', v_id)), true) x;
    IF v_now IS NULL THEN
      RETURN authz_int.scim_no(404, NULL, 'no group ' || p_id);
    ELSIF p_method = 'GET' THEN
      RETURN ROW(200, CASE WHEN v_members_too THEN v_now ELSE v_now - 'members' END, NULL)::authz_int.scim_answer;
    END IF;
  END IF;
  -- the group as the request leaves it: its name, its externalId, its members (NULL: as they are), and what the
  -- app's function gets of it (a PATCH: the group with the operations applied; else the body as it was sent)
  IF p_method = 'PATCH' THEN
    SELECT * INTO p FROM authz_int.scim_group_patch(p_body->'Operations',
      ARRAY(SELECT x.member->>'value' FROM jsonb_array_elements(v_now->'members') WITH ORDINALITY x(member, i) ORDER BY x.i),
      v_now->>'displayName', v_now->>'externalId');
    IF p.why IS NOT NULL THEN
      RETURN authz_int.scim_no(400, p.scim_type, p.why);
    END IF;
    v_name := p.name; v_external := p.external_id; v_members := CASE WHEN p.touched THEN p.members END;
    v_resource := jsonb_strip_nulls(v_now || jsonb_build_object('displayName', v_name, 'externalId', v_external))
                  || jsonb_build_object('members', authz_int.scim_values(p.members));
  ELSIF p_method <> 'DELETE' THEN
    v_resource := p_body;
    v_name := CASE WHEN jsonb_typeof(p_body->'displayName') = 'string' THEN p_body->>'displayName' END;
    v_external := CASE WHEN p_body ? 'externalId' THEN p_body->>'externalId' ELSE v_now->>'externalId' END;
    IF coalesce(v_name, '') = '' THEN
      RETURN authz_int.scim_no(400, 'invalidValue', 'displayName: a group has a name, a text that isn''t empty');
    ELSIF jsonb_typeof(p_body->'members') <> 'null' THEN   -- (members not said, a PUT's too: they stay as they are)
      SELECT * INTO m FROM authz_int.scim_members(p_body->'members', true);
      IF m.why IS NOT NULL THEN
        RETURN authz_int.scim_no(400, 'invalidValue', m.why);
      END IF;
      v_members := m.ids;
    END IF;
  END IF;
  -- its row is the app's to write, through the function the settings name: a new group, a deleted one, a whole
  -- one put, and a name or an externalId (where the settings name its column) that is no longer the row's
  IF p_method IN ('POST', 'DELETE') OR v_name IS DISTINCT FROM (v_now->>'displayName')
     OR (p_settings ? 'group_external_id' AND v_external IS DISTINCT FROM (v_now->>'externalId'))
     OR (p_method = 'PUT' AND v_function IS NOT NULL) THEN
    IF v_function IS NULL THEN
      RETURN authz_int.scim_no(501, NULL, 'the SCIM settings name no function that makes, changes or deletes a group (authz.set_scim: group_function)');
    END IF;
    SELECT * INTO c FROM authz_int.scim_call(v_function, v_type, v_id, v_resource);
    IF (c.refusal).status IS NOT NULL THEN
      RETURN c.refusal;
    ELSIF p_method = 'DELETE' THEN
      RETURN ROW(204, NULL, NULL)::authz_int.scim_answer;
    END IF;
    v_id := c.key;
  END IF;
  IF v_members IS NOT NULL THEN
    PERFORM authz.sync_members(v_type, v_id, v_relation, v_members);
  END IF;
  IF p_method = 'PATCH' THEN
    RETURN ROW(204, NULL, NULL)::authz_int.scim_answer;
  END IF;
  SELECT x.resources->0 INTO v_now FROM authz_int.scim_groups(p_settings, jsonb_build_array(jsonb_build_array('id', v_id)), true) x;
  RETURN ROW(CASE p_method WHEN 'POST' THEN 201 ELSE 200 END, v_now, CASE p_method WHEN 'POST' THEN 'Groups/' || v_id END)::authz_int.scim_answer;
END $f$;

-- An identity provider's SCIM request answered (RFC 7644): what a route got, in; what it answers, out.
--   SELECT status, body, location FROM authz.scim('PATCH', 'Groups/10', '', '{"Operations": [...]}', 'ak_...')
-- p_path: the path below the route, as the route read it (Groups/10); p_query: the query string as it was sent
-- (filter=displayName%20eq%20%22Engineering%22); p_token: the bearer token. location: for what was made (201), its
-- path below the route.
-- A request is the provider's when its token is an API key of the principal the settings name (authz.set_scim), and
-- its transaction is then signed in as that principal, as authz.login_key signs it in: the audit trail says who.
-- Nothing else says who asks: the app role may call this, and gets 401 without that key. A key limited to scopes
-- that write nothing reads, and changes nothing (403).
CREATE FUNCTION authz.scim(p_method text, p_path text, p_query text, p_body jsonb, p_token text,
  OUT status int, OUT body jsonb, OUT location text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_settings jsonb; k authz.api_keys; v_answer authz_int.scim_answer; v_method text := upper(coalesce(p_method, ''));
        v_path text := btrim(coalesce(p_path, ''), '/'); v_parts text[]; v_query jsonb;
BEGIN
  SELECT coalesce(jsonb_object_agg(substr(x.key, 6), x.value), '{}') INTO v_settings
  FROM authz.settings x WHERE starts_with(x.key, 'scim_');
  -- the key's principal is read before anyone is signed in: a key that is someone else's signs nobody in
  SELECT * INTO k FROM authz.api_keys x WHERE x.hash = encode(sha256(convert_to(coalesce(p_token, ''), 'UTF8')), 'hex');
  IF k.id IS NOT NULL AND (k.principal_type || ':' || k.user_id) IS NOT DISTINCT FROM (v_settings->>'principal') THEN
    BEGIN
      PERFORM authz.login_key(p_token);
    EXCEPTION WHEN invalid_authorization_specification THEN   -- revoked, expired, its principal gone, someone signed in
      k.id := NULL;
    END;
  ELSE
    k.id := NULL;
  END IF;
  v_parts := string_to_array(v_path, '/');
  IF k.id IS NULL THEN
    v_answer := authz_int.scim_no(401, NULL, 'the bearer token is not an API key of the principal the SCIM settings name');
  ELSIF v_method <> 'GET' AND NOT authz_int.writable() THEN
    v_answer := authz_int.scim_no(403, NULL, 'this key is read-only: it reads users and groups, and changes none');
  ELSE
    v_query := authz_int.scim_query(p_query);
    IF v_query IS NULL THEN
      v_answer := authz_int.scim_no(400, 'invalidSyntax', 'the query string''s escapes are no text');
    ELSIF v_parts[1] = 'Groups' AND cardinality(v_parts) <= 2 THEN
      v_answer := authz_int.scim_group(v_settings, v_method, v_parts[2], v_query, p_body);
    ELSE
      v_answer := authz_int.scim_no(404, NULL, 'nothing is served at ' || v_path);
    END IF;
  END IF;
  status := v_answer.status; body := v_answer.body; location := v_answer.location;
END $f$;

-- Name what the SCIM endpoint reads: the settings as one JSON object, which replaces the stored ones (an empty one
-- turns the endpoint off). For the tables' owner: the principal named here writes users and groups.
--   SELECT authz.set_scim('{"principal": "service:7", "group": "team.member", "group_name": "name"}')
-- principal (type:id): whose API key signs the provider in. group (type.relation): the groups, a relation
-- authz.sync_members takes; group_name, group_external_id: the columns of its table that hold a group's displayName
-- and externalId; group_function: the app's function that makes, changes and deletes a group. user_name,
-- user_external_id, user_active, user_function: the same for the users' table. page: the most a list answers
-- (100). A function is (p_id text, p_resource jsonb) RETURNS text: p_id NULL makes the row, p_resource NULL deletes
-- it, and it answers the row's key; it runs as the owner, so it is the owner's own. Each setting is checked now, so
-- that a mistake is found here and not at the provider's first request
CREATE FUNCTION authz.set_scim(p_settings jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_names text[] := ARRAY['principal', 'group', 'group_name', 'group_external_id', 'group_function', 'user_name', 'user_external_id', 'user_active', 'user_function', 'page']; v_set jsonb := '{}'; s record; v_type text; v_id text; v_name text; v_table text;
        v_column_type text; v_function text;
BEGIN
  IF p_settings IS NULL OR jsonb_typeof(p_settings) <> 'object' THEN
    RAISE EXCEPTION 'say the SCIM settings as a JSON object (an empty one turns the endpoint off)'
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ720';
  END IF;
  FOR s IN SELECT x.key AS name, jsonb_typeof(x.value) AS kind, x.value #>> '{}' AS said FROM jsonb_each(p_settings) x ORDER BY x.key LOOP
    IF s.name <> ALL (v_names) THEN
      RAISE EXCEPTION '% is no SCIM setting (they are: %)', s.name, array_to_string(v_names, ', ')
        USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ720';
    ELSIF s.kind NOT IN ('string', 'number', 'null') THEN
      RAISE EXCEPTION '%: write the setting as a text', s.name USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ720';
    ELSIF s.kind <> 'null' THEN
      v_set := v_set || jsonb_build_object(s.name, s.said);
    END IF;
  END LOOP;
  IF v_set <> '{}' THEN
    v_type := split_part(v_set->>'principal', ':', 1);
    v_id := substr(v_set->>'principal', length(v_type) + 2);
    IF coalesce(v_type, '') = '' OR v_id = '' THEN
      RAISE EXCEPTION 'principal: name whose API key signs the provider in, as type:id (service:7)'
        USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ720';
    ELSIF v_type <> 'user' AND NOT EXISTS (SELECT 1 FROM authz_int.types x WHERE x.name = v_type AND x.principal) THEN
      RAISE EXCEPTION 'principal %: no type % that signs in (user, or a type ... principal)', v_set->>'principal', v_type
        USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ720';
    ELSIF NOT authz_int.hold(v_type, authz_int.canon(v_type, v_id)) THEN
      RAISE EXCEPTION 'principal %: there is no % %', v_set->>'principal', v_type, v_id
        USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ720';
    END IF;
    v_set := v_set || jsonb_build_object('principal', v_type || ':' || authz_int.canon(v_type, v_id));
    IF v_set ? 'group' AND NOT authz_int.takes_members(v_set->>'group') THEN
      RAISE EXCEPTION 'group %: no relation with one table of members (it needs one source: table(group -> user), without where), as authz.sync_members takes',
        v_set->>'group' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ720';
    END IF;
    FOREACH v_name IN ARRAY ARRAY['group_name', 'group_external_id', 'group_function', 'user_name', 'user_external_id', 'user_active'] LOOP
      SELECT to_regclass(x.tbl)::text INTO v_table FROM authz_int.types x
      WHERE x.name = CASE WHEN v_name LIKE 'group%' THEN split_part(v_set->>'group', '.', 1) ELSE 'user' END;
      IF v_set ? v_name AND v_table IS NULL THEN
        RAISE EXCEPTION '% is a setting of the group: name it (group, as type.relation)', v_name
          USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ720';
      ELSIF v_name = 'group_name' AND v_set ? 'group' AND NOT v_set ? v_name THEN
        RAISE EXCEPTION 'group_name: name the column of % that holds a group''s displayName', v_table
          USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ720';
      END IF;
      CONTINUE WHEN NOT v_set ? v_name OR v_name = 'group_function';
      SELECT format_type(a.atttypid, a.atttypmod) INTO v_column_type FROM pg_attribute a
      WHERE a.attrelid = to_regclass(v_table) AND a.attname = v_set->>v_name AND a.attnum > 0 AND NOT a.attisdropped;
      IF v_column_type IS NULL THEN
        RAISE EXCEPTION '%: % has no column %', v_name, v_table, v_set->>v_name
          USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ720';
      ELSIF v_name = 'user_active' AND v_column_type <> 'boolean' THEN
        RAISE EXCEPTION 'user_active: %.% is %, and whether a user is active is a boolean', v_table, v_set->>v_name, v_column_type
          USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ720';
      END IF;
    END LOOP;
    -- a function of the app's is called as the owner: it is one the owner (or a role that is the owner's, or a
    -- superuser) owns, found by its schema and name, never through a search path
    FOREACH v_name IN ARRAY ARRAY['group_function', 'user_function'] LOOP
      CONTINUE WHEN NOT v_set ? v_name;
      SELECT format('%I.%I', n.nspname, p.proname) INTO v_function
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace JOIN pg_roles r ON r.oid = p.proowner, pg_namespace o
      WHERE p.oid = to_regprocedure((v_set->>v_name) || '(text, jsonb)') AND p.prokind = 'f' AND NOT p.proretset
        AND p.prorettype = 'text'::regtype AND o.nspname = 'authz_int' AND (r.rolsuper OR pg_has_role(p.proowner, o.nspowner, 'MEMBER'));
      IF v_function IS NULL THEN
        RAISE EXCEPTION '%: % is no function (text, jsonb) that returns text and belongs to the policy''s owner (write it with its schema)',
          v_name, v_set->>v_name USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ720';
      END IF;
      v_set := v_set || jsonb_build_object(v_name, v_function);
    END LOOP;
    IF v_set ? 'page' AND NOT (CASE WHEN v_set->>'page' ~ '^[0-9]{1,4}$' THEN (v_set->>'page')::int BETWEEN 1 AND 1000 ELSE false END) THEN
      RAISE EXCEPTION 'page: a whole number from 1 to 1000 (the most a list answers; 100 when it isn''t set)'
        USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ720';
    END IF;
  END IF;
  DELETE FROM authz.settings x WHERE starts_with(x.key, 'scim_');
  INSERT INTO authz.settings (key, value) SELECT 'scim_' || x.key, x.value FROM jsonb_each_text(v_set) x;
  PERFORM authz_int.audit('set_scim', NULL, NULL, NULL, NULL, NULL, NULL, v_set);
END $f$;

-- Leaks: SELECT * FROM authz.lint()  (administrators; run after schema changes)
CREATE OR REPLACE FUNCTION authz.lint() RETURNS TABLE (severity text, object text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r record; v_role oid := to_regrole('"conf_app"');
BEGIN
  IF v_role IS NULL THEN
    severity := 'error'; object := 'conf_app'; problem := 'the app role does not exist'; RETURN NEXT; RETURN;
  END IF;
  -- the app role itself
  FOR r IN SELECT rolsuper, rolbypassrls FROM pg_roles WHERE oid = v_role AND (rolsuper OR rolbypassrls) LOOP
    severity := 'error'; object := 'conf_app';
    problem := 'is a superuser or has BYPASSRLS: row-level security does not apply to it at all'; RETURN NEXT;
  END LOOP;
  FOR r IN SELECT p.oid::regrole AS parent FROM pg_roles p
           WHERE p.oid <> v_role AND (p.rolsuper OR p.rolbypassrls) AND pg_has_role(v_role, p.oid, 'MEMBER') LOOP
    severity := 'error'; object := 'conf_app';
    problem := format('is a member of %s, which bypasses row-level security', r.parent); RETURN NEXT;
  END LOOP;
  -- the policy's owner (or a member of it): its sessions are believed unsigned, it may read rowstile's tables
  -- (the session key among them) and turn row-level security off (applying refuses it, AZ624: this finds a grant made since)
  FOR r IN SELECT n.nspowner::regrole AS owner FROM pg_namespace n, pg_roles a
           WHERE n.nspname = 'authz_int' AND a.oid = v_role AND NOT a.rolsuper AND pg_has_role(v_role, n.nspowner, 'MEMBER') LOOP
    severity := 'error'; object := 'conf_app';
    problem := format('is the policy''s owner %s, or a member of it: who is signed in is believed without a signature, and it may read rowstile''s tables and turn row-level security off. The app role must be a role of its own: not the tables'' owner or the policy''s, nor a member of either', r.owner);
    RETURN NEXT;
  END LOOP;
  -- rowstile's own objects: nobody but the owner uses them, except for what the policy grants
  FOR r IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."folder__edit"', 'authz_int."folder__edit__direct"', 'authz_int."project__edit"', 'authz_int."project__member"', 'authz_int."project__owner"', 'authz_int."project__service"', 'authz_int."project__view"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"conf_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"conf_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.folders:column owner_id:items"', '"app.folders:column owner_id:why"', '"app.folders:rules:explain"', '"app.folders:update:items"', '"app.folders:update:refuse"', '"app.folders:update:why"', '"app.inbox:insert:items"', '"app.inbox:insert:refuse"', '"app.inbox:insert:why"', '"app.inbox:rules:explain"', '"app.notes:delete:items"', '"app.notes:delete:why"', '"app.notes:insert:items"', '"app.notes:insert:refuse"', '"app.notes:insert:why"', '"app.notes:rules:explain"', '"app.notes:update:items"', '"app.notes:update:refuse"', '"app.notes:update:why"', '"app.projects:rules:explain"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"conf_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.sign_out()', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.scim(text, text, text, jsonb, text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.list_links(text, bigint)', 'authz.revoke_link(text, bigint, text)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, bigint, text, text, text[])', 'authz.roles_of(text, bigint)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, bigint, timestamptz)', 'authz.can(text, bigint, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.perms(text, bigint)', 'authz.share(text, text, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, bigint, text)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, bigint, text)']::regprocedure[])) LOOP
    severity := 'error'; object := r.object;
    problem := format('%s holds %s on it, which the policy doesn''t give (a default privilege of the owner, or a grant made since the last apply): the next apply takes it back, or %s', r.who, r.privilege, r.stmt);
    RETURN NEXT;
  END LOOP;
  -- schemas on the search path of the functions that run as the owner, which others may create in
  FOR r IN SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(authz_int.policy_path()) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_' LOOP
    severity := 'error'; object := r.schema;
    problem := format('is on the search path of rowstile''s functions that run as the owner, and %s may create in it: a function there can take the place of a built-in one and run as the owner. REVOKE CREATE ON SCHEMA %I FROM %s, or apply with a search path without it', r.who, r.schema, r.who);
    RETURN NEXT;
  END LOOP;
  -- the audit trail's guard, which fires in every replication role (ENABLE ALWAYS): ENABLE TRIGGER ALL, which a
  -- data-only pg_restore --disable-triggers ends with, puts it back for ordinary sessions only
  FOR r IN SELECT t.name, g.tgenabled::text AS mode
           FROM (VALUES ('authz_audit_append_only'), ('authz_audit_no_truncate')) t (name)
           LEFT JOIN pg_trigger g ON g.tgrelid = 'authz.audit'::regclass AND g.tgname = t.name
           WHERE g.tgenabled IS DISTINCT FROM 'A' LOOP
    severity := 'warning'; object := 'authz.audit';
    problem := format('the trigger %s %s. rowstile reapply puts it back, in every replication role', r.name,
      CASE r.mode
        WHEN 'O' THEN 'guards it in ordinary sessions only: one with session_replication_role = replica may change the trail (ENABLE TRIGGER ALL leaves it so, as at the end of a data-only pg_restore --disable-triggers)'
        WHEN 'R' THEN 'guards it with session_replication_role = replica only: an ordinary session may change the trail'
        WHEN 'D' THEN 'that guards it is off: the trail may be changed'
        ELSE 'that guards it is missing: the trail may be changed' END);
    RETURN NEXT;
  END LOOP;
  -- governed tables
  FOR r IN SELECT c.oid::regclass AS tbl, c.relrowsecurity, c.relowner,
                  c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."folders"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) x) AS governed
           FROM pg_class c WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."folders"', '"app"."inbox"', '"app"."notes"', '"app"."projects"', '"app"."services"', '"app"."users"']::text[]) x) LOOP
    -- (FORCE ROW LEVEL SECURITY is no way out: an owner may turn it off again, and row-level security with it)
    IF pg_has_role(v_role, r.relowner, 'MEMBER') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('is owned by %s (or a role it belongs to): an owner skips row-level security, and may turn it off, FORCE ROW LEVEL SECURITY or not. The app role must not own the tables: ALTER TABLE %s OWNER TO the role that applies the policy', 'conf_app', r.tbl);
      RETURN NEXT;
    END IF;
    IF NOT r.relrowsecurity AND r.governed THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('row-level security is off, so the policy''s rules don''t apply to it: %s reads and writes every row it has privileges on. Apply the policy again (it turns it on), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', 'conf_app', r.tbl);
      RETURN NEXT;
    ELSIF NOT r.relrowsecurity AND has_any_column_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row (the policy has no rules for this table): fine for a directory, otherwise add rules', 'conf_app');
      RETURN NEXT;
    END IF;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which skips row-level security: REVOKE TRUNCATE ON %s FROM %s', 'conf_app', r.tbl, 'conf_app');
      RETURN NEXT;
    END IF;
    -- (TRIGGER, the other privilege GRANT ALL gives beside the four commands: with it a role puts a function of
    -- its own on the table, and what writes the table's rows as its owner runs it as the owner)
    IF has_table_privilege(v_role, r.tbl, 'TRIGGER') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may make triggers on it (TRIGGER, which GRANT ALL gives): a foreign key''s action that writes its rows (ON DELETE or ON UPDATE CASCADE, SET NULL) runs their functions as the table''s owner, whom no rule holds: REVOKE TRIGGER ON %s FROM %s', 'conf_app', r.tbl, 'conf_app');
      RETURN NEXT;
    END IF;
    -- (REFERENCES, the last one GRANT ALL gives: a foreign key is checked as the tables' owner, whatever the rules
    -- hide, so a table of the role's own that names a row says whether the row is there; one column's is enough)
    IF r.governed AND has_any_column_privilege(v_role, r.tbl, 'REFERENCES') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may make foreign keys to it (REFERENCES, which GRANT ALL gives): a table of its own that names one of its rows tells whether the row is there, hidden or not: REVOKE REFERENCES ON %s FROM %s', 'conf_app', r.tbl, 'conf_app');
      RETURN NEXT;
    END IF;
  END LOOP;
  -- policies on governed tables that rowstile didn't make (left from before, or made by a migration) and that
  -- apply to the app role: Postgres joins permissive policies with OR, so one widens what the rules allow
  FOR r IN SELECT p.polname, p.polrelid::regclass AS tbl, p.polpermissive,
                  CASE p.polcmd WHEN 'r' THEN 'select' WHEN 'a' THEN 'insert' WHEN 'w' THEN 'update'
                                WHEN 'd' THEN 'delete' ELSE 'every command' END AS cmd
           FROM pg_policy p
           LEFT JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
           WHERE p.polrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."folders"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) x)
             AND coalesce(d.description, '') NOT IN ('rowstile')
             AND EXISTS (SELECT 1 FROM unnest(p.polroles) o
                         WHERE CASE WHEN o = 0 THEN true ELSE pg_has_role(v_role, o, 'MEMBER') END)
           ORDER BY p.polrelid::regclass::text, p.polname LOOP
    object := r.tbl::text;
    IF r.polpermissive THEN
      severity := 'error';
      problem := format('the policy %I (%s) on it is not rowstile''s: Postgres joins a table''s policies with OR, so it lets %s through whatever the rules say. DROP POLICY %I ON %s, and say what it allowed in the policy file', r.polname, r.cmd, 'conf_app', r.polname, r.tbl);
    ELSE
      severity := 'info';
      problem := format('the restrictive policy %I (%s) on it is not rowstile''s: %s gets less than the rules give, and a write it refuses fails with Postgres''s own message, not a reason', r.polname, r.cmd, 'conf_app');
    END IF;
    RETURN NEXT;
  END LOOP;
  -- tables beside the policy's (in their schemas) that it doesn't name: nothing filters what the app role reads there
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind IN ('r', 'p') AND NOT c.relispartition AND NOT c.relrowsecurity
             AND c.relnamespace IN (SELECT k.relnamespace FROM unnest(ARRAY['"app"."folders"', '"app"."inbox"', '"app"."notes"', '"app"."projects"', '"app"."services"', '"app"."users"', '"app"."members"', '"app"."project_services"']::text[]) x
                                    JOIN pg_class k ON k.oid = to_regclass(x))
             AND c.oid NOT IN (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"app"."folders"', '"app"."inbox"', '"app"."notes"', '"app"."projects"', '"app"."services"', '"app"."users"', '"app"."members"', '"app"."project_services"']::text[]) x
                               WHERE to_regclass(x) IS NOT NULL)
             AND has_any_column_privilege(v_role, c.oid, 'SELECT')
           ORDER BY c.oid::regclass::text LOOP
    severity := 'info'; object := r.tbl::text;
    problem := format('%s may read every row, and the policy doesn''t name this table: fine for a lookup table, otherwise give it a type and rules', 'conf_app');
    RETURN NEXT;
  END LOOP;
  -- partitions and inheritance children: used directly, they skip the rules of the table above (apply turns
  -- row-level security on for the ones there are then; later ones are found here), and TRUNCATE skips the
  -- triggers for TRUNCATE alone that are not right there (the sync mirror's). The tables above: those
  -- with rules, and those rowstile watches (a trigger of its own on them)
  FOR r IN WITH RECURSIVE x(tbl, governed) AS (
             SELECT to_regclass(t), true FROM unnest(ARRAY['"app"."folders"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) t
             UNION SELECT DISTINCT g.tgrelid::regclass, false FROM pg_trigger g
             JOIN pg_proc f ON f.oid = g.tgfoid AND f.pronamespace = 'authz_int'::regnamespace
             WHERE NOT g.tgisinternal AND g.tgrelid NOT IN (SELECT to_regclass(t) FROM unnest(ARRAY['"app"."folders"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) t
                                                           WHERE to_regclass(t) IS NOT NULL)
               AND NOT EXISTS (SELECT 1 FROM pg_description c WHERE c.objoid = g.oid AND c.classoid = 'pg_trigger'::regclass
                               AND c.description = 'rowstile: the trigger of the table above, for the rows stored here')),
           d(oid, top, governed) AS (
             SELECT i.inhrelid, i.inhparent, x.governed FROM pg_inherits i JOIN x ON i.inhparent = x.tbl
             UNION SELECT i.inhrelid, d.top, d.governed FROM pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass AS part, d.top::regclass AS tbl, d.governed, k.relrowsecurity
           FROM d JOIN pg_class k ON k.oid = d.oid LOOP
    IF has_table_privilege(v_role, r.part, 'TRUNCATE') THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may TRUNCATE it, which skips row-level security: REVOKE TRUNCATE ON %s FROM %s', r.tbl, 'conf_app', r.part, 'conf_app');
      RETURN NEXT;
    END IF;
    IF has_table_privilege(v_role, r.part, 'TRIGGER') THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may make triggers on it (TRIGGER, which GRANT ALL gives): a foreign key''s action that writes its rows runs their functions as the table''s owner, whom no rule holds: REVOKE TRIGGER ON %s FROM %s', r.tbl, 'conf_app', r.part, 'conf_app');
      RETURN NEXT;
    END IF;
    IF r.governed AND has_any_column_privilege(v_role, r.part, 'REFERENCES') THEN
      severity := 'info'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may make foreign keys to it (REFERENCES, which GRANT ALL gives): a table of its own that names one of its rows tells whether the row is there, hidden or not: REVOKE REFERENCES ON %s FROM %s', r.tbl, 'conf_app', r.part, 'conf_app');
      RETURN NEXT;
    END IF;
    -- (on a table without rules, statements on it run the triggers of the table above as their own: the next loop
    -- finds one made since that lacks them)
    -- (one column's privilege is enough: no DELETE has columns)
    IF r.governed AND NOT r.relrowsecurity AND (has_any_column_privilege(v_role, r.part, 'INSERT') OR has_any_column_privilege(v_role, r.part, 'UPDATE')
                                 OR has_table_privilege(v_role, r.part, 'DELETE') OR has_any_column_privilege(v_role, r.part, 'SELECT')) THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may use it directly, without %s''s rules or the triggers that keep inheritance and the audit current: apply the policy again (it turns row-level security on for it), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', r.tbl, 'conf_app', r.tbl, r.part);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- partitions and tables that inherit, made since the last apply: Postgres runs a table's row triggers for its
  -- own rows and its partitions' only, and its statement triggers for statements on it only; applying gives
  -- them to each table under it (whatever the app role may do there: the owner's statements count too, and
  -- rows written through the table above need no privilege of their own)
  FOR r IN SELECT c.child, k.relispartition AS part, (SELECT i.inhparent::regclass FROM pg_inherits i WHERE i.inhrelid = c.child LIMIT 1) AS above,
                  string_agg(c.name::text, ', ' ORDER BY c.name) AS names
           FROM authz_int.child_triggers() c JOIN pg_class k ON k.oid = c.child GROUP BY c.child, k.relispartition LOOP
    severity := 'error'; object := r.child::text;
    IF r.part THEN
      problem := format('is a partition of %s, and was made since the policy was last applied: Postgres runs a table''s statement triggers for statements on it only, so a statement on this partition doesn''t keep inheritance, shares and the audit current (missing here: %s). Apply the policy again (it makes them)', r.above, r.names);
    ELSE
      problem := format('inherits from %s, and was made since the policy was last applied: Postgres runs a table''s row triggers for its own rows only, and its statement triggers for statements on it only, so a rule on a column is not checked on the rows stored here, their shares stay when their key changes, and a statement on this table doesn''t keep inheritance, shares and the audit current (missing here: %s). Apply the policy again (it makes them)', r.above, r.names);
    END IF;
    RETURN NEXT;
  END LOOP;
  -- a rule on the row after a change whose trigger runs after the update (its table has a generated column, which
  -- only the written row holds: governance.trigger_after_where_generated): Postgres's own checks on the row speak
  -- before the rule there. Said once a table (a partition's trigger is its table's)
  FOR r IN SELECT g.tgrelid::regclass AS tbl,
                  string_agg('update ' || substr(g.tgname, 20) || ' after', ', ' ORDER BY g.tgname) AS rules
           FROM pg_trigger g JOIN pg_proc f ON f.oid = g.tgfoid AND f.pronamespace = 'authz_int'::regnamespace
           WHERE NOT g.tgisinternal AND g.tgparentid = 0 AND g.tgtype & 19 = 17 AND g.tgname LIKE 'authz\_update\_after %'
           GROUP BY g.tgrelid ORDER BY g.tgrelid::regclass::text LOOP
    severity := 'info'; object := r.tbl::text;
    problem := format('has a generated column, so what its rules say of the row after a change (%s) is checked once the row is written, not before: a unique index or a foreign key of the table speaks first, and its error tells of a row the user may not see', r.rules);
    RETURN NEXT;
  END LOOP;
  -- unique constraints on governed tables tell people that rows they cannot see exist
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisunique AND NOT i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."folders"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) x)
             AND has_any_column_privilege(v_role, i.indrelid, 'INSERT') LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('a unique index on %s: inserting a duplicate fails even when the existing row is hidden, which tells the user it exists', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- primary keys the app role may choose (a key column it may insert or update, not GENERATED ALWAYS; not one the
  -- index only INCLUDEs, which it holds but is not keyed by): the same
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."folders"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) x)
             AND EXISTS (SELECT 1 FROM pg_attribute a
                         WHERE a.attrelid = i.indrelid AND a.attnum = ANY ((i.indkey::int2[])[0:i.indnkeyatts - 1]) AND a.attidentity <> 'a'
                           AND (has_column_privilege(v_role, i.indrelid, a.attnum, 'INSERT')
                                OR has_column_privilege(v_role, i.indrelid, a.attnum, 'UPDATE'))) LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('the primary key of %s, which %s may choose: an insert with the id of a hidden row fails, which tells the user it exists. Let the database make the ids (GENERATED ALWAYS AS IDENTITY, or random uuids), or revoke INSERT and UPDATE on the key', r.tbl, 'conf_app');
    RETURN NEXT;
  END LOOP;
  -- masked columns must only be readable through their view
  FOR r IN SELECT m.tbl, m.col, m.view FROM authz_int.masked_columns m
           WHERE CASE WHEN EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(m.tbl) AND a.attname = m.col
                                   AND a.attnum > 0 AND NOT a.attisdropped)
                      THEN has_column_privilege(v_role, m.tbl, m.col, 'SELECT') ELSE false END LOOP
    severity := 'error'; object := to_regclass(r.tbl)::text || '.' || r.col;
    problem := format('the policy masks it, but %s may read it from the table (a GRANT to the role, a role it belongs to, or PUBLIC): read it through %s and revoke that', 'conf_app', r.view);
    RETURN NEXT;
  END LOOP;
  -- tables holding relationships (memberships, links) the app role may change directly
  FOR r IN SELECT to_regclass(v.tbl) AS tbl, v.readers, v.typed
           FROM (VALUES ('"app"."members"', 'project.member', false), ('"app"."project_services"', 'project.service', false)) v(tbl, readers, typed) LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which empties memberships without row-level security: REVOKE TRUNCATE ON %s FROM %s', 'conf_app', r.tbl, 'conf_app');
      RETURN NEXT;
    END IF;
    -- (a type's table was asked above)
    IF NOT r.typed AND has_table_privilege(v_role, r.tbl, 'TRIGGER') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may make triggers on it (TRIGGER, which GRANT ALL gives): a foreign key''s action that writes its rows (ON DELETE or ON UPDATE CASCADE, SET NULL) runs their functions as the table''s owner, whom no rule holds: REVOKE TRIGGER ON %s FROM %s', 'conf_app', r.tbl, 'conf_app');
      RETURN NEXT;
    END IF;
    IF (has_any_column_privilege(v_role, r.tbl, 'INSERT') OR has_any_column_privilege(v_role, r.tbl, 'UPDATE')
        OR has_table_privilege(v_role, r.tbl, 'DELETE'))
       AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl) THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may change it, and it decides who is in what: anyone could add themselves. Revoke the write privileges, or give it rules', 'conf_app');
      RETURN NEXT;
    END IF;
    -- ... or read in full: who is linked to what (a type's table without rules is named above)
    IF NOT r.typed AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl)
       AND has_any_column_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row, and the policy reads it for %s: who is linked to what is readable. Fine where that is no secret, otherwise give it a type and rules', 'conf_app', r.readers);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- columns that grant a relation, changed by anyone who may update the row
  FOR r IN SELECT * FROM (VALUES ('"app"."notes"', 'project_id', 'note.project', 'relation note.project project_id', 'nobody'), ('"app"."notes"', 'author_id', 'note.author', 'relation note.author author_id', 'nobody'), ('"app"."folders"', 'parent_id', 'folder.parent', 'relation folder.parent parent_id', 'nobody')) v(tbl, col, what, loc, ask)
           WHERE tbl IS NOT NULL LOOP
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attname = r.col
               AND a.attnum > 0 AND NOT a.attisdropped)
       AND has_column_privilege(v_role, r.tbl, r.col, 'UPDATE') THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('grants %s (%s), and anyone who may update the row may change it: add a rule such as "update %s : %s"', r.what, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.ask);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- rules for a command the app role has no privilege for (one column's is enough for a read, an insert or
  -- an update: the app may write some columns only)
  FOR r IN SELECT to_regclass(v.tbl) AS tbl, v.cmd FROM (VALUES ('"app"."folders"', 'select'), ('"app"."folders"', 'update'), ('"app"."inbox"', 'insert'), ('"app"."inbox"', 'select'), ('"app"."notes"', 'delete'), ('"app"."notes"', 'insert'), ('"app"."notes"', 'select'), ('"app"."notes"', 'update'), ('"app"."projects"', 'select')) v(tbl, cmd)
           WHERE v.tbl IS NOT NULL LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF r.cmd = 'delete' THEN
      CONTINUE WHEN has_table_privilege(v_role, r.tbl, 'DELETE');
    ELSE
      CONTINUE WHEN has_any_column_privilege(v_role, r.tbl, r.cmd);
    END IF;
    severity := 'warning'; object := r.tbl::text;
    problem := format('the policy has a rule for %s, but %s has no %s privilege on the table: the rule never applies, and the statement fails with Postgres''s own "permission denied for table". GRANT %s ON %s TO %s, or make the rule "%s : nobody"', r.cmd, 'conf_app', upper(r.cmd), upper(r.cmd), r.tbl, 'conf_app', r.cmd);
    RETURN NEXT;
  END LOOP;
  -- relations named like a type that signs in
  FOR r IN SELECT * FROM (VALUES ('project', 'service', 'relation project.service')) v(type, rel, loc)
           WHERE type IS NOT NULL LOOP
    severity := 'info'; object := r.type || '.' || r.rel;
    problem := format('is named like the type %s (%s), which signs in: alone in a rule it reads like any %s, and it is this row''s. A name that says what the relation is (author, owner) reads better', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.rel);
    RETURN NEXT;
  END LOOP;
  severity := 'info'; object := 'service';
  problem := 'signs in, but has no manage_keys permission, so nobody can make API keys for it: add can manage_keys = ... (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'type service'), '?') || ')';
  RETURN NEXT;
  -- columns that move a row under another, with nothing checking where it moves to
  FOR r IN SELECT * FROM (VALUES ('"app"."folders"', 'parent_id', 'parent', 'relation app.folders parent parent_id')) v(tbl, col, rel, loc)
           WHERE tbl IS NOT NULL LOOP
    -- (a composite key's columns are 'org_id, parent_id': any of them it may update)
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attnum > 0 AND NOT a.attisdropped
               AND a.attname::text = ANY (string_to_array(r.col, ', ')) AND has_column_privilege(v_role, r.tbl, a.attnum, 'UPDATE')) THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('moves a row under another (%s, %s), and nothing checks where it moves to, so anyone who may update a row may put it inside something they may not change: add a rule such as "update %s after : %s.edit"', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.rel);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- views over governed tables that run with their owner's rights
  FOR r IN SELECT DISTINCT v.oid::regclass AS view, d.refobjid::regclass AS tbl
           FROM pg_depend d JOIN pg_rewrite w ON w.oid = d.objid JOIN pg_class v ON v.oid = w.ev_class
           LEFT JOIN pg_description ds ON ds.objoid = v.oid AND ds.classoid = 'pg_class'::regclass
           WHERE d.classid = 'pg_rewrite'::regclass AND d.refclassid = 'pg_class'::regclass
             AND d.refobjid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."folders"', '"app"."inbox"', '"app"."notes"', '"app"."projects"', '"app"."services"', '"app"."users"', '"app"."members"', '"app"."project_services"']::text[]) x)
             AND v.oid <> d.refobjid AND v.relkind IN ('v', 'm')
             AND v.relnamespace NOT IN (to_regnamespace('authz_gen'), to_regnamespace('authz_int'))
             AND coalesce(ds.description, '') NOT IN ('rowstile masked view')
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=true'], false)
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=on'], false)
             AND has_any_column_privilege(v_role, v.oid, 'SELECT') LOOP
    severity := 'error'; object := r.view::text;
    problem := format('%s may read this view of %s, and views run with their owner''s rights, so row-level security does not apply: ALTER VIEW %s SET (security_invoker = on)', 'conf_app', r.tbl, r.view);
    RETURN NEXT;
  END LOOP;
  -- functions that read governed tables as their owner
  FOR r IN SELECT p.oid::regprocedure AS fn FROM pg_proc p
           WHERE p.prosecdef AND p.pronamespace NOT IN (to_regnamespace('authz'), to_regnamespace('authz_int'),
                                                       to_regnamespace('authz_gen'), 'pg_catalog'::regnamespace)
             AND has_function_privilege(v_role, p.oid, 'EXECUTE')
             AND p.prokind IN ('f', 'p')
             AND EXISTS (SELECT 1 FROM unnest(ARRAY['app.folders', 'app.inbox', 'app.notes', 'app.projects', 'app.services', 'app.users', 'app.members', 'app.project_services']::text[]) x
                         WHERE lower(replace(pg_get_functiondef(p.oid), '"', '')) ~
                               ('(from|join|update|into|table|only)\s+(' || lower(split_part(x, '.', 1)) || '\.)?'
                                || lower(split_part(x, '.', 2)) || '([^a-z0-9_$]|$)')) LOOP
    severity := 'warning'; object := r.fn::text;
    problem := 'SECURITY DEFINER, callable by the app role, and seems to use a governed table: it reads rows without row-level security unless its owner is subject to it';
    RETURN NEXT;
  END LOOP;
  -- lookups the permission views make
  FOR r IN SELECT * FROM (VALUES ('"app"."users"', 'id', 'user: find one by its key, for checks and write rules', NULL), ('"app"."services"', 'id', 'service: find one by its key, for checks and write rules', NULL), ('"app"."projects"', 'owner_id', 'project.owner: find objects by owner_id', NULL), ('"app"."members"', 'project_id', 'project.member: find the members of an object', NULL), ('"app"."members"', 'user_id', 'project.member: find what a subject is in', NULL), ('"app"."project_services"', 'project_id', 'project.service: find the members of an object', NULL), ('"app"."project_services"', 'service_id', 'project.service: find what a subject is in', NULL), ('"app"."projects"', 'id', 'project: find one by its key, for checks and write rules', NULL), ('"app"."notes"', 'project_id', 'note.project: find objects by project_id', NULL), ('"app"."notes"', 'author_id', 'note.author: find objects by author_id', NULL), ('"app"."notes"', 'id', 'note: find one by its key, for checks and write rules', NULL), ('"app"."inbox"', 'recipient_id', 'message.recipient: find objects by recipient_id', NULL), ('"app"."inbox"', 'id', 'message: find one by its key, for checks and write rules', NULL), ('"app"."folders"', 'parent_id', 'folder.parent: find objects by parent_id', NULL), ('"app"."folders"', 'owner_id', 'folder.owner: find objects by owner_id', NULL), ('"app"."folders"', 'id', 'folder: find one by its key, for checks and write rules', NULL)) v(tbl, col, why, alone) WHERE tbl IS NOT NULL LOOP
    CONTINUE WHEN to_regclass(r.tbl) IS NULL;
    -- a plain view can't have an index: the tables under it answer the lookups
    CONTINUE WHEN (SELECT c.relkind FROM pg_class c WHERE c.oid = to_regclass(r.tbl)) = 'v';
    -- an index whose first columns are these (one, or a composite key's, in any order), or what serves a (type, id)
    -- pair alone (its ids where they are two columns, its type where its id is one): a finished one, with no
    -- condition (the lookups are joins, which a partial index doesn't serve), as rowstile indexes counts them; its key
    -- columns only (an index on (a) INCLUDE (b) is not sorted by b)
    IF NOT EXISTS (SELECT 1 FROM pg_index i, unnest(ARRAY[r.col, r.alone]) w(cs)
                   WHERE w.cs IS NOT NULL AND i.indrelid = to_regclass(r.tbl) AND i.indisvalid AND i.indpred IS NULL
                     AND (SELECT array_agg(a.attname::text ORDER BY a.attname)
                          FROM unnest((i.indkey::int2[])[0:least(cardinality(string_to_array(w.cs, ', ')), i.indnkeyatts) - 1]) k
                          JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k)
                         = (SELECT array_agg(c ORDER BY c) FROM unnest(string_to_array(w.cs, ', ')) c)) THEN
      severity := 'performance'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('no index starts with %s (%s): CREATE INDEX ON %s (%s)',
                        CASE WHEN r.col LIKE '%, %' THEN 'these columns' ELSE 'this column' END, r.why, to_regclass(r.tbl),
                        (SELECT string_agg(quote_ident(c), ', ') FROM unnest(string_to_array(r.col, ', ')) c));
      RETURN NEXT;
    END IF;
  END LOOP;
END $f$;

-- The partitions of each table with rules and the tables that inherit from one: row-level security on, with
-- no policies of their own, so they are read and written through it only (read directly, they would skip its rules
-- and triggers). Every apply and every migration: one made or attached since is closed too (it alone is locked,
-- as CHILD_TRIGGERS locks only one that lacks the triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i
             WHERE i.inhparent = ANY (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"app"."folders"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) x)
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

REVOKE SELECT ON ALL TABLES IN SCHEMA authz_gen, authz_int FROM "conf_app";
GRANT SELECT ON authz_gen.policy_lines, authz_int."folder__edit", authz_int."folder__edit__direct", authz_int."project__edit", authz_int."project__member", authz_int."project__owner", authz_int."project__service", authz_int."project__view" TO "conf_app";

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."folder__edit"', 'authz_int."folder__edit__direct"', 'authz_int."project__edit"', 'authz_int."project__member"', 'authz_int."project__owner"', 'authz_int."project__service"', 'authz_int."project__view"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"conf_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"conf_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.folders:column owner_id:items"', '"app.folders:column owner_id:why"', '"app.folders:rules:explain"', '"app.folders:update:items"', '"app.folders:update:refuse"', '"app.folders:update:why"', '"app.inbox:insert:items"', '"app.inbox:insert:refuse"', '"app.inbox:insert:why"', '"app.inbox:rules:explain"', '"app.notes:delete:items"', '"app.notes:delete:why"', '"app.notes:insert:items"', '"app.notes:insert:refuse"', '"app.notes:insert:why"', '"app.notes:rules:explain"', '"app.notes:update:items"', '"app.notes:update:refuse"', '"app.notes:update:why"', '"app.projects:rules:explain"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"conf_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.sign_out()', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.scim(text, text, text, jsonb, text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.list_links(text, bigint)', 'authz.revoke_link(text, bigint, text)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, bigint, text, text, text[])', 'authz.roles_of(text, bigint)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, bigint, timestamptz)', 'authz.can(text, bigint, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.perms(text, bigint)', 'authz.share(text, text, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, bigint, text)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, bigint, text)']::regprocedure[])) LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowstile''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO "conf_app";

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

DO $gf$
DECLARE f regprocedure;
BEGIN
  FOR f IN SELECT p.oid::regprocedure FROM pg_proc p WHERE p.pronamespace = 'authz_gen'::regnamespace
           AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.folders:column owner_id:items"', '"app.folders:column owner_id:why"', '"app.folders:rules:explain"', '"app.folders:update:items"', '"app.folders:update:refuse"', '"app.folders:update:why"', '"app.inbox:insert:items"', '"app.inbox:insert:refuse"', '"app.inbox:insert:why"', '"app.inbox:rules:explain"', '"app.notes:delete:items"', '"app.notes:delete:why"', '"app.notes:insert:items"', '"app.notes:insert:refuse"', '"app.notes:insert:why"', '"app.notes:rules:explain"', '"app.notes:update:items"', '"app.notes:update:refuse"', '"app.notes:update:why"', '"app.projects:rules:explain"']::text[]) LOOP
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO %I', f, 'conf_app');
  END LOOP;
END $gf$;

